// === BEFORE INHERITANCE: DUPLICATION HELL ===
class BadCar {
    String vin;
    int speed;
    int doors;
    void accelerate() { speed += 10; }
}
class BadTruck {
    String vin;
    int speed;
    double cargoCapacity;
    void accelerate() { speed += 10; }
}

// === AFTER INHERITANCE: CLEAN & DRY ===
class Vehicle {
    protected String vin;
    protected int speed;

    public Vehicle(String vin) {
        this.vin = vin;
        this.speed = 0;
    }

    public void accelerate(int amount) {
        this.speed += amount;
        System.out.println(vin + " accelerating to " + speed + " km/h");
    }
}

class Car extends Vehicle {
    private int doors;

    public Car(String vin, int doors) {
        super(vin);
        this.doors = doors;
    }

    public void openTrunk() {
        System.out.println("Car " + vin + " opened trunk with " + doors + " doors");
    }
}

public class InheritanceDemo {
    public static void main(String[] args) {
        Car myCar = new Car("VIN-8821", 4);
        // Inherited method from Vehicle
        myCar.accelerate(50);
        // Specialized method from Car
        myCar.openTrunk();
    }
}

