class Account {
    protected String accountNumber;
    protected double balance;

    public Account(String accountNumber, double balance) {
        this.accountNumber = accountNumber;
        this.balance = balance;
    }

    // Fix bug once here: prevent negative deposits
    public void deposit(double amount) {
        if (amount <= 0) {
            System.out.println("Invalid deposit amount: " + amount);
            return;
        }
        this.balance += amount;
        System.out.println("Deposited $" + amount + ", new balance: $" + balance);
    }
}

class PremiumSavingsAccount extends Account {
    public PremiumSavingsAccount(String id, double initial) {
        super(id, initial);
    }
}

public class BugFixDemo {
    public static void main(String[] args) {
        PremiumSavingsAccount savings = new PremiumSavingsAccount("SAV-101", 500.0);
        // Subclass immediately benefits from the central deposit guard
        savings.deposit(-50.0); // Rejected!
        savings.deposit(200.0); // Accepted!
    }
}

