        wm.washCycle();
    }
}

class Account {
    protected String accountNumber;
    protected double balance;

    public Account(String accountNumber, double balance) {
        this.accountNumber = accountNumber;
        this.balance = balance;
    }
}

class FixedDepositAccount extends Account {
    private int lockPeriodMonths;

    public FixedDepositAccount(String accountNumber, double balance, int lockPeriodMonths) {
        super(accountNumber, balance);
        this.lockPeriodMonths = lockPeriodMonths;
    }

    public double calculateMaturityAmount(double rate) {
        return balance + (balance * rate * lockPeriodMonths / 1200.0);
    }

    public void displaySummary(double rate) {
        double maturity = calculateMaturityAmount(rate);
        System.out.println("Account " + accountNumber + " locked for " + lockPeriodMonths + " months. Maturity amount: $" + maturity);
    }
}

public class Main {
    public static void main(String[] args) {
        FixedDepositAccount fd = new FixedDepositAccount("FD-991", 10000.0, 12);
        fd.displaySummary(7.0);
    }
}

