class Employee {
    protected String name;
    protected double salary;

    public Employee(String name, double salary) {
        this.name = name;
        this.salary = salary;
    }

    public void giveRaise(double amount) {
        if (amount <= 0) {
            System.out.println("Rejected invalid raise: " + amount);
            return;
        }
        this.salary += amount;
        System.out.println("Employee " + name + " salary: " + salary);
    }
}

class Developer extends Employee {
    public Developer(String name, double salary) {
        super(name, salary);
    }
}

public class Main {
    public static void main(String[] args) {
        Developer dev = new Developer("Alice", 80000.0);
        dev.giveRaise(5000.0);
        dev.giveRaise(-2000.0);
    }
}

class MediaItem {
    protected String id;
    protected String title;
    protected boolean isAvailable;

    public MediaItem(String id, String title) {
        this.id = id;
        this.title = title;
        this.isAvailable = true;
    }
}

class Video extends MediaItem {
    private int durationMinutes;

    public Video(String id, String title, int durationMinutes) {
        super(id, title);
        this.durationMinutes = durationMinutes;
    }

    public void streamVideo(int quality) {
        System.out.println("Streaming '" + title + "' at " + quality + "p (Duration: " + durationMinutes + "m)");
    }
}

class Book extends MediaItem {
    private int pageCount;

    public Book(String id, String title, int pageCount) {
        super(id, title);
        this.pageCount = pageCount;
    }

    public void readBook() {
        System.out.println("Reading '" + title + "' (" + pageCount + " pages)");
    }
}

public class Main {
    public static void main(String[] args) {
        Video vid = new Video("V1", "Clean Architecture", 120);
        Book bk = new Book("B1", "Design Patterns", 450);
        vid.streamVideo(1080);
        bk.readBook();
    }
}
